import{_ as t,o as n,c as a,ag as i}from"./chunks/framework.cyF4XceO.js";const p=JSON.parse('{"title":"0044 — Graduation evidence is implementation independence, honestly attributed","description":"","frontmatter":{},"headers":[],"relativePath":"spec/decisions/0044-graduation-evidence-is-implementation-independence.md","filePath":"spec/decisions/0044-graduation-evidence-is-implementation-independence.md"}'),o={name:"spec/decisions/0044-graduation-evidence-is-implementation-independence.md"};function s(r,e,d,c,h,l){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="_0044-—-graduation-evidence-is-implementation-independence-honestly-attributed" tabindex="-1">0044 — Graduation evidence is implementation independence, honestly attributed <a class="header-anchor" href="#_0044-—-graduation-evidence-is-implementation-independence-honestly-attributed" aria-label="Permalink to &quot;0044 — Graduation evidence is implementation independence, honestly attributed&quot;">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-08-23</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Two normative documents made a person a prerequisite. <code>versioning.md</code> required &quot;two independently operated hosts&quot; for a lane graduation, and <code>project-lifecycle.md</code> required &quot;two distinct host subjects with two independently named maintainers&quot; for a Stable Form. In an ecosystem whose every implementation is currently written and operated by one maintainer, those words make v1 unreachable regardless of how much evidence the contracts earn — not because the contract is unproven, but because of an organizational fact the spec cannot change.</p><p>The criterion was never really about payroll. What two maintainers were a proxy for is the failure mode that kills portability claims: a contract that is only implementable by copying the reference implementation&#39;s private model. Independence of <em>implementations</em> — distinct codebases, neither derived from the other&#39;s host internals, both passing the same corpus, at least one carrying real traffic — measures that directly. Independence of <em>people</em> was the proxy, and a proxy that cannot be satisfied stops measuring anything.</p><p>The maintainer directed this realization explicitly (2026-08-23).</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>The personnel criterion is replaced by an implementation criterion, and the personnel fact is disclosed instead of required.</strong></p><p>A graduation&#39;s host-evidence prerequisite is now: <strong>two independent host implementations from distinct codebases — neither derived from the other&#39;s host internals — exercising the same lifecycle semantics through the same conformance corpus, at least one of them operating in production for real consumers.</strong> When those implementations share a maintainer, the graduation ADR MUST say so by name; the shared authorship is a recorded limitation of the evidence, never a hidden one.</p><p>Everything else stands unchanged: the compatibility window, end-to-end materialization of every optional surface the lane declares, cross-publisher package installation (the package publisher must not be a consuming host — a role separation this ecosystem can satisfy), the deprecation and revocation exercises, and the rule that a graduation is its own ADR minting new exact identities (<a href="./0039-a-lane-is-minted-for-one-of-two-reasons.html">decision 0039</a>, <a href="./0037-immutability-begins-at-stable.html">decision 0037</a>).</p><p><code>versioning.md</code> and <code>project-lifecycle.md</code> are updated with this record, as the ADR rule requires.</p><h2 id="what-this-does-not-do" tabindex="-1">What this does not do <a class="header-anchor" href="#what-this-does-not-do" aria-label="Permalink to &quot;What this does not do&quot;">​</a></h2><p>It does not lower the bar to a declaration. A second implementation still has to exist, be independent in code, pass the corpus, and one of the two still has to carry production traffic. It does not remove the third-party dimension from the ecosystem&#39;s ambitions — an external implementation remains the strongest possible evidence and a graduation ADR should cite one when it exists. It changes only what is <em>required</em>: the spec stops requiring an organizational fact it cannot cause.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>v1 becomes reachable by doing work this ecosystem can actually do: a second host implementation (takosumi is the designated candidate) built against the spec rather than extracted from the reference host, driven by <code>portable-host-conformance</code> and the runtime corpus, with the reference host as the other subject. The graduation ADR that eventually cites this rule will carry the maintainer disclosure, and a reader evaluating the Stable claim gets the true shape of its evidence.</p>',15)])])}const u=t(o,[["render",s]]);export{p as __pageData,u as default};
